#!/usr/bin/env python3
"""Clean messy customer CSV: whitespace, casing, dates, phones, dupes, missing values."""
import csv
import re
from datetime import datetime

SRC = "sample_data.csv"
DST = "cleaned_data.csv"
FIELDS = ["id", "name", "email", "signup_date", "phone", "city"]

# First matching format wins; %m-%d-%Y before %d-%m-%Y (sample data assumed US order)
DATE_FORMATS = ("%Y/%m/%d", "%Y-%m-%d", "%m-%d-%Y", "%m/%d/%Y", "%d-%m-%Y")
EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
NON_DIGIT_RE = re.compile(r"\D")


def clean_text(v):
    return re.sub(r"\s+", " ", (v or "").strip())


def clean_email(v):
    v = clean_text(v).lower()
    return v if EMAIL_RE.match(v) else ""


def clean_date(v):
    v = clean_text(v)
    if not v:
        return ""
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(v, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return ""  # unparseable -> blank


def clean_phone(v):
    digits = NON_DIGIT_RE.sub("", clean_text(v))
    if len(digits) == 11 and digits.startswith("1"):
        digits = digits[1:]
    if len(digits) == 10:
        return f"{digits[:3]}-{digits[3:6]}-{digits[6:]}"
    return ""


def main():
    with open(SRC, newline="", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))

    stats = {"input": len(rows), "duplicates": 0, "invalid_emails": 0, "missing_dates": 0}
    seen_ids = set()
    cleaned = []

    for row in rows:
        rid = clean_text(row["id"])
        if rid in seen_ids:
            stats["duplicates"] += 1
            continue
        seen_ids.add(rid)

        email = clean_email(row["email"])
        if not email:
            stats["invalid_emails"] += 1
        date = clean_date(row["signup_date"])
        if not date:
            stats["missing_dates"] += 1

        cleaned.append({
            "id": rid,
            "name": clean_text(row["name"]).title(),
            "email": email,
            "signup_date": date,
            "phone": clean_phone(row["phone"]),
            "city": clean_text(row["city"]).title(),
        })

    with open(DST, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=FIELDS)
        writer.writeheader()
        writer.writerows(cleaned)

    print(f"rows in: {stats['input']}, rows out: {len(cleaned)}")
    print(f"duplicates dropped: {stats['duplicates']}")
    print(f"invalid/missing emails blanked: {stats['invalid_emails']}")
    print(f"missing/unparseable dates blanked: {stats['missing_dates']}")


if __name__ == "__main__":
    main()
